// spec: specs/orders.md §32 · кейс .qa/tests/orders/ord-45-walk-in-bad-sku-note.md
// seed: tests/seed.admin.spec.ts
// #1ee7e8 (באג, עבר QA 28.10, commit 69f5029): «מכירה מיידית» — товар с сохранённым неверным מק"ט добавляется с оранжевой заметкой
//   «נוסף: <имя>. המק״ט שלו (<код>) שגוי — ספרת הביקורת לא תקינה. כדאי לתקן אותו בקטלוג.»; код не найден + неверная
//   контрольная — «לא נמצא מוצר עם המק״ט <код>. ספרת הביקורת של הברקוד שגויה — בדקו את הספרות.»; не найден с верной — без подсказки.
// Данные: свой товар «QA-AUTO-1ee7e8w-<ts>» (неверный EAN-13 через «שמירה בכל זאת»), без остатка. «רישום המכירה» НЕ нажимается —
//   продажа не завершается; корзина не хранится (только в памяти страницы) — после ухода со страницы проверяем, что она пуста.
//   afterAll удаляет товар. @data.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { deleteProduct } from './_qa-order';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });
test.describe.configure({ mode: 'serial' });

function checkDigit(body: string) {
  let n = 0;
  for (let i = body.length - 1, w = 3; i >= 0; i--, w = 4 - w) n += Number(body[i]) * w;
  return (10 - (n % 10)) % 10;
}
const TS = Date.now().toString().slice(-7);
const BODY = `28${TS}${Math.floor(Math.random() * 900 + 100)}`;
const BAD = BODY + ((checkDigit(BODY) + 1) % 10);
const UNKNOWN_BODY = `27${TS}${Math.floor(Math.random() * 900 + 100)}`;
const UNKNOWN_BAD = UNKNOWN_BODY + ((checkDigit(UNKNOWN_BODY) + 1) % 10);
const UNKNOWN_GOOD = UNKNOWN_BODY + checkDigit(UNKNOWN_BODY);
const P = `QA-AUTO-1ee7e8w-${TS}`;
const EMPTY = 'עדיין לא נוספו פריטים — חפש מוצר למטה כדי להתחיל.';
let created = false;

async function openWalkIn(page: Page) {
  await page.goto('/orders/walk-in');
  await expect(page.getByRole('heading', { level: 1, name: 'מכירה מיידית' })).toBeVisible({ timeout: 30_000 });
  return page.getByRole('combobox', { name: 'חיפוש מוצר להוספה למכירה' });
}

test.describe('orders — מכירה מיידית: מק"ט עם ספרת ביקורת שגויה (#1ee7e8)', () => {
  test.beforeAll(async ({ browser }) => {
    test.setTimeout(90_000);
    const ctx = await browser.newContext({ storageState: path.resolve(__dirname, '../../../auth/admin.json'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    const page = await ctx.newPage();
    try {
      await page.goto('/catalog/new');
      await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible({ timeout: 30_000 });
      await page.getByRole('textbox', { name: /שם מוצר/ }).fill(P);
      await page.getByRole('textbox', { name: /מק"ט/ }).fill(BAD);
      await page.getByRole('spinbutton', { name: 'מחיר בסיס' }).fill('1');
      await page.getByRole('button', { name: 'שמירה', exact: true }).click();
      created = true;
      await page.getByRole('dialog').getByRole('button', { name: 'שמירה בכל זאת' }).click();
      await expect(page.getByText('נוסף לקטלוג.')).toBeVisible({ timeout: 15_000 });
    } finally { await ctx.close(); }
  });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(90_000);
    if (!created) return;
    const ctx = await browser.newContext({ storageState: path.resolve(__dirname, '../../../auth/admin.json'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    try { await deleteProduct(await ctx.newPage(), P); } finally { await ctx.close(); }
  });

  test('הוספה לפי מק"ט שגוי + Enter — המוצר נוסף עם הערה כתומה «…שגוי — ספרת הביקורת לא תקינה. כדאי לתקן אותו בקטלוג.»; בלי רישום מכירה #1ee7e8 @desktop @orders @data', async ({ page }) => {
    const search = await openWalkIn(page);
    await search.fill(BAD);
    await expect(page.getByRole('listbox', { name: 'תוצאות חיפוש מוצרים' }).getByRole('option', { name: new RegExp(P) })).toBeVisible({ timeout: 20_000 });
    await search.press('Enter');
    await expect(page.getByRole('textbox', { name: `כמות — ${P}`, exact: true })).toHaveValue('1', { timeout: 15_000 });
    const note = page.getByRole('status').filter({ hasText: `נוסף: ${P}.` });
    await expect(note).toHaveText(`נוסף: ${P}. המק״ט שלו (${BAD}) שגוי — ספרת הביקורת לא תקינה. כדאי לתקן אותו בקטלוג.`);
    // «оранжевая» — цвет статуса partial (как у «ספרת הביקורת… אין ברקוד» в תעודה), а не обычный зелёный «נוסף»
    const color = await note.evaluate((el) => {
      const t = [el, ...el.querySelectorAll('*')].find((e) => /status-partial/.test((e as HTMLElement).className)) as HTMLElement | undefined;
      return t ? getComputedStyle(t).color : null;
    });
    expect(color, 'заметка в цвете предупреждения (status-partial)').not.toBeNull();
    // продажу не завершаем — уходим; корзина не сохраняется
    await page.getByRole('button', { name: 'חזרה להזמנות' }).click();
    await expect(page).toHaveURL(/\/orders$/);
    await openWalkIn(page);
    await expect(page.getByText(EMPTY)).toBeVisible();
  });

  test('קוד שלא נמצא: ספרת ביקורת שגויה — «…ספרת הביקורת של הברקוד שגויה — בדקו את הספרות.»; תקינה — רק «לא נמצא מוצר…» #1ee7e8 @desktop @orders @prod-safe', async ({ page }) => {
    const search = await openWalkIn(page);
    await search.fill(UNKNOWN_BAD);
    await search.press('Enter');
    await expect(page.getByText(`לא נמצא מוצר עם המק״ט ${UNKNOWN_BAD}. ספרת הביקורת של הברקוד שגויה — בדקו את הספרות.`, { exact: true })).toBeVisible({ timeout: 15_000 });
    await search.fill(UNKNOWN_GOOD);
    await search.press('Enter');
    await expect(page.getByText(`לא נמצא מוצר עם המק״ט ${UNKNOWN_GOOD}.`, { exact: true })).toBeVisible({ timeout: 15_000 });
    await expect(page.getByText(/ספרת הביקורת/)).toHaveCount(0);
    await expect(page.getByText(EMPTY)).toBeVisible();
  });
});
